export const escape=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function safeURL(value,{image=false}={}){try{const u=new URL(value,location.origin);if(u.origin===location.origin&&/^https?:$/.test(u.protocol))return u.href;if(u.protocol==='https:')return u.href;}catch{}return image?'/assets/hero/hero-1.jpg':'/courses.html';}
export function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.hidden=false;clearTimeout(el.timer);el.timer=setTimeout(()=>el.hidden=true,6000);}
export function dialogEvents(){document.addEventListener('click',e=>{if(e.target.closest('[data-close-dialog]'))e.target.closest('dialog')?.close();});document.querySelectorAll('dialog').forEach(d=>d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}}));}
export const readPreference=key=>{try{return localStorage.getItem(key);}catch{return null;}};
export const writePreference=(key,value)=>{try{localStorage.setItem(key,value);}catch{}};
export const slugify=s=>String(s||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,100).replace(/-$/,'');
export function courseURL(c){if(c.slug)return '/learn/'+encodeURIComponent(c.slug);return ['corset','blazer','pant','beading','hippad'].includes(c.id)?'/courses/'+encodeURIComponent(c.id)+'.html':'/courses/class.html?id='+encodeURIComponent(c.id);}
export function postURL(p){if(p.slug)return '/read/'+encodeURIComponent(p.slug);return ['measure-before-you-cut','sewing-toolkit','finishing-details'].includes(p.slug)?'/journal/'+encodeURIComponent(p.slug)+'.html':'/journal/article.html?id='+encodeURIComponent(p.id);}
export function courseCard(c){const title=c.title||c.pageTitle||'Masterclass',image=c.image||c.flyerUrl,description=c.summary||c.desc||c.description;return `<article class="card" data-course-card data-id="${escape(c.id)}" data-category="${escape(c.category||'Construction')}"><a class="card-image" href="${courseURL(c)}"><img src="${escape(safeURL(image,{image:true}))}" alt="${escape(title)} course flyer" loading="lazy" width="600" height="750"><span class="card-label">${escape(c.category||'Construction')}</span></a><div class="card-body"><p class="eyebrow">${escape(c.duration)}</p><h3><a href="${courseURL(c)}">${escape(title)}</a></h3><p>${escape(description)}</p><div class="card-bottom">${shareButton(title,courseURL(c))}<strong>${escape(String(c.fee||'Ask Gracy').split(' · ')[0])}</strong><a href="${courseURL(c)}" aria-label="Explore ${escape(title)}">↗</a></div></div></article>`;}
export function postCard(p){return `<article class="card"><a class="card-image" href="${postURL(p)}"><img src="${escape(safeURL(p.image,{image:true}))}" alt="${escape(p.title)}" width="600" height="400" loading="lazy"></a><div class="card-body"><p class="eyebrow">${escape(p.category||'Studio notes')}</p><h3><a href="${postURL(p)}">${escape(p.title)}</a></h3><p>${escape(p.excerpt)}</p><div class="story-links"><a class="text-link" href="${postURL(p)}">Read the story ↗</a>${shareButton(p.title,postURL(p))}</div></div></article>`;}
export const shareIcon='<svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><circle cx="18" cy="5" r="3"/><circle cx="6" cy="12" r="3"/><circle cx="18" cy="19" r="3"/><path d="m8.6 10.5 6.8-4M8.6 13.5l6.8 4"/></svg>';
export function shareButton(title,url=''){return `<button class="share-button" type="button" data-share="${escape(url)}" data-share-title="${escape(title)}" aria-label="Share ${escape(title)}">${shareIcon}<span>Share</span></button>`;}
export const popupDesigns=['atelier','sunrise','postcard','ribbon','lookbook','gallery'];
export function popupClass(design){return 'popup-design-'+(popupDesigns.includes(design)?design:'atelier');}
